#pragma once

// Official UMDPlay logo, embedded as a PNG byte array at build time.
//
// The bytes are generated by cmake/EmbedAsset.cmake into
// <build>/generated/umdplay_logo_data.cpp from assets/umdplay_logo.png, so the
// WMC hub header and the SDL window icon work from a bare release binary (the
// bundles ship no assets/ directory). See CMakeLists.txt.
extern const unsigned char umdplay_logo_png[];
extern const unsigned int  umdplay_logo_png_len;
